def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    index = 0
    length = len(line)
    while index < length:
        ch = line[index]
        if in_quotes:
            if ch == '"':
                # Check for escaped quote
                if index + 1 < length and line[index + 1] == '"':
                    current.append('"')
                    index += 1
                else:
                    in_quotes = False
            else:
                current.append(ch)
        else:
            if ch == '"':
                in_quotes = True
            elif ch == ',':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        index += 1
    fields.append(''.join(current))
    return fields
